import{_ as t,o as a,c as s,a3 as n,j as e,a as r}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/zeugnisformulare/reports-dokumentenverwaltung-1.png",l="/bilder/zeugnisformulare/reports-dokumentenverwaltung-2.png",d="/bilder/zeugnisformulare/zeugnisdruck-zeugnisablage-dateiname.png",o="/bilder/zeugnisformulare/reports-dokumentenverwaltung-3.png",g="/bilder/zeugnisformulare/reports-dokumentenverwaltung-4-dq-und-gruppen.png",c="/bilder/zeugnisformulare/reports-dokumentenverwaltung-5-gruppe.png",_=JSON.parse('{"title":"Reportausgaben und Zeugnisse archivieren","description":"","frontmatter":{"title":"Reportausgaben und Zeugnisse archivieren","source_pageid":1573,"source_revision":7124},"headers":[],"relativePath":"reporting/zeugnisformulare/dokumentenverwaltung-und-zeugnisarchivierung.md","filePath":"reporting/zeugnisformulare/dokumentenverwaltung-und-zeugnisarchivierung.md"}'),m={name:"reporting/zeugnisformulare/dokumentenverwaltung-und-zeugnisarchivierung.md"};function h(p,i,k,f,v,b){return a(),s("div",null,[...i[0]||(i[0]=[n('<h1 id="reportausgaben-und-zeugnisse-archivieren" tabindex="-1">Reportausgaben und Zeugnisse archivieren <a class="header-anchor" href="#reportausgaben-und-zeugnisse-archivieren" aria-label="Permalink to &quot;Reportausgaben und Zeugnisse archivieren&quot;">​</a></h1><p>Richten Sie Dokumentenablage und Zeugnisverzeichnis ein, um Reportausgaben als PDF zu archivieren. Die beiden Ablagen unterscheiden sich bei Benennung und Aufbewahrung älterer Ausgaben.</p><p>SchILD bietet unter bestimmten Umständen die Möglichkeit, generierte Reports als .pdf zu archivieren.</p><ul><li>Reports, welche mit der Datenquelle <em>&quot;Schueler&quot;</em> erzeugt werden, können in der <em>Dokumentenablage</em> abgelegt werden.</li><li>Zeugnisse können in die <em>Zeugnisablage</em> gelegt werden.</li></ul>',4),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),r("Wichtig")]),e("p",null,"Hierbei ist zu beachten, dass die Dokumentenablage entsprechend der Löschfristen bei der automatischen Prüfung mit geprüft und bei Ablauf der Löschfristen mit gelöscht wird.")],-1),n('<h2 id="_1-dokumentenablage" tabindex="-1">1. Dokumentenablage <a class="header-anchor" href="#_1-dokumentenablage" aria-label="Permalink to &quot;1. Dokumentenablage&quot;">​</a></h2><p>Die Dokumentenablage kann zum Beispiel genutzt werden, um Warnbriefe wegen Nichtversetzung, Warnungen wegen zu vieler Fehlstunden oder auch besondere Anschreiben an die Erziehungsberechtigten digital abzulegen.</p><p><a href="/bilder/zeugnisformulare/reports-dokumentenverwaltung-1.png"><img src="'+u+'" alt="Einstellungen zur Dokumentenverwaltung." loading="lazy"></a></p><p><em>Einstellungen zur Dokumentenverwaltung.</em></p><p>Um die Dokumentenverwaltung und Zeugnisarchivierung zu aktivieren, müssen entsprechende Ordner angegeben werden. Dies ist über <em>Verwaltung</em> ➜ <em>Einstellungen</em> ➜ <em>Dokumentenverwaltung</em> möglich.</p><p>Hier in diesem Fenster lassen sich nun für beide Archivierungsmöglichkeiten getrennt Ordner setzen. Wurde ein Ordner eingestellt, stehen die Dokumentenverwaltung beziehungsweise die Zeugnisarchivierung zur Verfügung.</p>',6),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),r("Hinweis")]),e("p",null,"In größeren Systemen werden diese Verzeichnisse als Netzlaufwerke angelegt werden, so dass alle Personen gleiche, auf einem Server liegende Verzeichnis verwenden.")],-1),n(`<p>Bei der Dokumentenverwaltung kann die <em>Dateimaske</em> eingestellt werden. Diese bestimmt, wie die archivierten Dateien später benannt sind. Der Standard</p><pre><code>&quot;&lt;nvgd&gt;\\&lt;f&gt;_&lt;d&gt;&quot;
</code></pre><p>sieht kryptisch aus, bedeutet aber im Klartext, dass erst für jede Person ein Verzeichnis angelegt wird, das aus Name, Vorname, Geburtsdatum besteht, also z.B. &quot;Müller, Hans, 30_09_2013&quot;. In diesem Verzeichnis werden dann die Dokumente mit dem Dateinamen (<em>&lt;f&gt;</em> für <em>file</em>), gefolgt von einem Unterstrich &quot;_&quot; und dem Datum der Reportgenerierung (<em>&lt;d&gt;</em> für <em>date</em>) abgelegt.</p><p><a href="/bilder/zeugnisformulare/reports-dokumentenverwaltung-2.png"><img src="`+l+'" alt="Konfigurieren der Dateimaske per Menü." loading="lazy"></a></p><p><em>Konfigurieren der Dateimaske per Menü.</em></p><p>Öffnen Sie <strong>Dateimaske bearbeiten</strong>, um Verzeichnis- und Dateinamen ohne direkte Eingabe der Platzhalter zusammenzustellen.</p><ol><li>Zeigen Sie mit der Maus auf ein <strong>Merkmal</strong> in der Mitte.</li><li>Halten Sie die linke Maustaste gedrückt und ziehen Sie das Merkmal nach links in den <strong>Verzeichnisnamen</strong> oder nach rechts in den <strong>Dateinamen</strong>.</li><li>Lassen Sie die Maustaste los. Diese Bedienung heißt <strong>Drag-and-drop</strong>.</li><li>Ändern Sie die Reihenfolge bei Bedarf mit den kleinen roten Pfeilen.</li></ol><p>Hier im Beispiel wurde noch die Uhrzeit der Reporterzeugung zum Dateinamen hinzugefügt, was am zusätzlichen Schalter <em>&quot;&lt;z&gt;&quot;</em> in der Dateimaske zu sehen ist.</p><p>Entscheiden Sie sich für eine sinnvolle Struktur der Ordner. Existiert dieser Ordner nicht, wird er bei der Erzeugung eines Dokuments angelegt.</p><h2 id="_2-archivierte-dokumente-offnen" tabindex="-1">2. Archivierte Dokumente öffnen <a class="header-anchor" href="#_2-archivierte-dokumente-offnen" aria-label="Permalink to &quot;2. Archivierte Dokumente öffnen&quot;">​</a></h2>',10),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),r("Tipp")]),e("p",null,"Im Dokumentenordner können auch eigene Dokumente wie pdf-Dateien oder Dokumente des verwendeten Textverarbeitungsprogramms abgelegt und mit einem Doppelklick aus der SchILD-NRW-Dokumentenverwaltung heraus gestartet werden.")],-1),n(`<p>Ein <code>Doppelklick</code> auf Ordner klappt diese auf und zu.</p><p>Ein <code>Doppelklick</code> auf eine der Dateien startet diese mit dem in Windows für diese Datei verknüpften Programm.</p><p>Mit der <code>Rechten Maustaste</code> öffnen sich das für diese Datei beziehungsweise für Ordner verwendete Windows-Kontextmenü, so dass zum Beispiel Ordner extern im Windows-Explorer geöffnet werden können.</p><h2 id="_3-zeugnisverzeichnis" tabindex="-1">3. Zeugnisverzeichnis <a class="header-anchor" href="#_3-zeugnisverzeichnis" aria-label="Permalink to &quot;3. Zeugnisverzeichnis&quot;">​</a></h2><p>Wurde das Zeugnisverzeichnis gesetzt, werden dort die Dateien mit einem Namen abgelegt, der folgendem Schema entspricht:</p><pre><code> Name, Vorname, Geb.-Datum, Klasse des gedruckten Lernabschnitts, Name der Reportvorlage.pdf
</code></pre><p><a href="/bilder/zeugnisformulare/zeugnisdruck-zeugnisablage-dateiname.png"><img src="`+d+'" alt="Ein Beispieldateiname nach dem hier erklärten Schema." loading="lazy"></a></p><p><em>Ein Beispieldateiname nach dem hier erklärten Schema.</em></p><p>Somit würde zum Beispiel nach einem derartigen Schema eine Datei in der Dokumentenablage benannt werden.</p>',9),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),r("Hinweis")]),e("p",null,"Bei diesem Verzeichnis ist zu beachten, dass Dateien darin nicht das Datum oder andere Werte, die für das Dokumentenverzeichnis eingestellt werden können, beinhalten. Somit wird immer nur das letzte Zeugnis - einer bestimmten Anlage - abgelegt."),e("p",null,"Um Zeugnisse vergangener Lernabschnitte zu erhalten, sind die passenden Zeugnisse in Ordner der entsprechenden Lernabschnitte zu kopieren. Alternativ ist das Zeugnisverzeichnis als Dokumentation des jeweils letzten Standes mit dem aktuellsten Zeugnis zu sehen."),e("p",null,"Sollen die Zeugnisse automatisch passend benannt werden, kann entschieden werden, die Dokumentenablage auch zur Zeugnisarchivierung zu verwenden.")],-1),n('<h2 id="_4-verwendung-der-verzeichnisse" tabindex="-1">4. Verwendung der Verzeichnisse <a class="header-anchor" href="#_4-verwendung-der-verzeichnisse" aria-label="Permalink to &quot;4. Verwendung der Verzeichnisse&quot;">​</a></h2><p><a href="/bilder/zeugnisformulare/reports-dokumentenverwaltung-3.png"><img src="'+o+'" alt="Neue Schaltflächen zur Archivierung." loading="lazy"></a></p><p><em>Neue Schaltflächen zur Archivierung.</em></p><p>Wurde die Dokumentenverwaltung aktiviert, stehen bei der Generierung von Reports neue Schaltflächen zur Verfügung:</p><ul><li><strong>Drucker mit Archivierung</strong>: Dies generiert den Report wie gewohnt, der zu einem Drucker gesendet werden kann und generiert ihn im Anschluss noch einmal erneut, um ihn als .pdf in den jeweiligen Schülerordner abzulegen. <strong>Drucker ohne Archivierung</strong> ist die Schaltfläche, mit ein Report einfach nur zum Druck erzeugt wird.</li><li><strong>Nur Archivierung (in Dokumentenablage)</strong> generiert den Report direkt in die Dokumentenablage. Dies ist sinnvoll, wenn ein Report schon &quot;ohne Archivierung&quot; gedruckt wurde, er nun aber auch noch archiviert werden soll.</li><li><strong>Archivierung in Zeugnisverzeichnis</strong>: Legt den Report in das Zeugnisarchiv. Es sollten nur Zeugnisse - und eventuell vergleichbare Reports - dorthin archiviert werden.</li></ul>',5),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),r("Hinweis")]),e("p",null,"Da die Reports zweimal komplett erstellt werden, sind eventuelle anzuklickende Einstellungen oder Eingaben eines Reports bei einer Archivierung auch doppelt vorzunehmen. Dies betrifft etwa die Frage, ob mit Rand gedruckt werden soll oder (noch) fehlende Projektkurstitel für Projektkurse der Q1.")],-1),n('<h2 id="_5-voraussetzungen-im-report-prufen" tabindex="-1">5. Voraussetzungen im Report prüfen <a class="header-anchor" href="#_5-voraussetzungen-im-report-prufen" aria-label="Permalink to &quot;5. Voraussetzungen im Report prüfen&quot;">​</a></h2><p>Sollte ein Report nicht in die Dokumentenverwaltung abgelegt werden können, prüfen Sie, ob alle dieser drei Bedingungen erfüllt sind:</p><ul><li>die <em>Datenquelle Schueler</em> muss für den Report ausgewählt sein</li><li>es muss eine <em>Gruppierung</em> bezüglich eines Datenfeldes der Datenquelle im Report vorhanden sein, z.B. nach Schueler_Id</li><li>Auswahl <em>Drucker mit Archivierung</em> oder <em>nur Archivierung (in Dokumentenverwaltung)</em> im Druckmenü</li></ul><h2 id="_6-datenquelle-und-schulergruppe-konfigurieren" tabindex="-1">6. Datenquelle und Schülergruppe konfigurieren <a class="header-anchor" href="#_6-datenquelle-und-schulergruppe-konfigurieren" aria-label="Permalink to &quot;6. Datenquelle und Schülergruppe konfigurieren&quot;">​</a></h2><p><a href="/bilder/zeugnisformulare/reports-dokumentenverwaltung-4-dq-und-gruppen.png"><img src="'+g+'" alt="Datenquellen und Gruppen einstellen." loading="lazy"></a></p><p><em>Datenquellen und Gruppen einstellen.</em></p><p>Gehen Sie über <em>Bericht</em>, um über <em>Datenquellen</em> die Datenquelle <em>Schueler</em> einzustellen.</p><p>Über dieses Dropdown-Menü können auch <em>Gruppen...</em> konfiguriert werden.</p><p><a href="/bilder/zeugnisformulare/reports-dokumentenverwaltung-5-gruppe.png"><img src="'+c+'" alt="Setzen der Gruppe Schueler.ID." loading="lazy"></a></p><p><em>Setzen der Gruppe Schueler.ID.</em></p><p>Die Gruppe <em>Schueler.ID</em> erzeugt einen Gruppenwechsel bei Wechsel des Schülers, so dass der Dokumentenverwaltung signalisiert wird, den Ordner zu wechseln.</p><p>Die Gruppe kann auch ansonsten im Report &quot;unsichtbar&quot; sein, das heißt, dass sie im eigentlichen Report nicht weiter verwendet wird.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Dokumentenverwaltung_und_Zeugnisarchivierung" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7124.</p>',14)])])}const w=t(m,[["render",h]]);export{_ as __pageData,w as default};
